<template>
  <main class="assistant"><el-card class="chat-card"><template #header><div class="header"><div><h1>AI养老金融助手</h1><span>用简单的话，陪您了解养老金融知识</span></div><el-button @click="router.push('/dashboard')">返回首页</el-button></div></template>
    <section class="messages"><div v-if="!messages.length" class="empty">您好，我可以陪您了解养老金、养老规划和数字金融安全。</div><div v-for="(item,index) in messages" :key="index" :class="['message',item.role]"><b>{{item.role==='user'?'我':'助手'}}</b><p>{{item.content}}</p></div></section>
    <el-form class="composer" @submit.prevent="submit"><el-input v-model="question" type="textarea" :rows="3" maxlength="300" show-word-limit placeholder="例如：老人如何做好养老规划？"/><el-button type="primary" size="large" native-type="submit" :loading="loading">发送问题</el-button></el-form><el-alert v-if="notice" :title="notice" type="info" :closable="false"/><section v-if="lastAnswer" class="answer-meta"><strong>回答可信度：{{Math.round(confidence*100)}}%</strong><span>{{knowledgeUsed?'已引用知识库':'基于通用金融知识'}}</span></section><section v-if="sources.length" class="sources"><h2>参考知识</h2><div v-for="(s,index) in sources" :key="index"><strong>{{s.title}} · {{s.category}}</strong><p>{{s.content}}</p></div></section>
  </el-card></main>
</template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {chat} from '../api/assistant';const router=useRouter(),question=ref(''),loading=ref(false),notice=ref(''),conversationId=ref<number>(),messages=ref<{role:string,content:string}[]>([]),sources=ref<{title:string,category:string,content:string}[]>([]),confidence=ref(0),knowledgeUsed=ref(false),lastAnswer=ref('');async function submit(){if(!question.value.trim())return;const text=question.value;messages.value.push({role:'user',content:text});question.value='';loading.value=true;try{const r:any=await chat({question:text,conversationId:conversationId.value});const data=r.data.data;conversationId.value=data.conversationId;messages.value.push({role:'assistant',content:data.answer});lastAnswer.value=data.answer;confidence.value=data.confidence||0;knowledgeUsed.value=!!data.knowledgeUsed;notice.value=data.safetyNotice;sources.value=data.sources||[]}catch(e){ElMessage.error('助手暂时无法回应，请稍后重试')}finally{loading.value=false}}</script>
<style scoped>.assistant{min-height:100vh;background:#f4f7fb;padding:24px}.chat-card{max-width:860px;margin:auto}.header{display:flex;justify-content:space-between;align-items:center}h1{font-size:28px;margin:0 0 6px;color:#1769aa}.header span{font-size:18px;color:#6b7280}.messages{min-height:420px;max-height:58vh;overflow:auto;padding:16px}.empty{font-size:22px;color:#6b7280;padding:100px 20px;text-align:center}.message{display:flex;gap:12px;margin:16px 0;font-size:20px}.message b{min-width:48px;color:#1769aa}.message p{margin:0;padding:12px 16px;border-radius:8px;background:#eef5fb;line-height:1.7}.message.user{justify-content:flex-end}.message.user b{order:2;color:#555}.message.user p{order:1;background:#e8f5e9}.composer{display:flex;gap:12px;align-items:flex-end}.composer .el-input{flex:1}.answer-meta{display:flex;gap:20px;margin-top:18px;padding:14px;background:#eef7ee;color:#256b35;font-size:18px}.sources{margin-top:20px;padding:16px;background:#f7fafc;border-left:4px solid #1769aa}.sources h2{font-size:22px;margin:0 0 8px}.sources p{margin:4px 0 12px;line-height:1.6}@media(max-width:600px){.assistant{padding:8px}.header{align-items:flex-start}.header h1{font-size:23px}.composer{display:block}.composer .el-button{margin-top:10px;width:100%}}</style>
